async function submitService(event) {
	event.preventDefault();
	const form = new FormData(event.target);
	if (event.submitter.value === "import") await api("/admin-ui/admin/services/import", {
		method: "POST",
		body: JSON.stringify({
			studio_service_id: form.get("studio_service_id"),
			name: form.get("name"),
			route_pattern: blankToUndefined(form.get("route_pattern")),
			default_pricing: form.get("estimated_cost_usd") ? {
				cost_mode: form.get("cost_mode"),
				estimated_cost_usd: Number(form.get("estimated_cost_usd"))
			} : void 0
		})
	});
	else await api("/admin-ui/admin/services", {
		method: "POST",
		body: JSON.stringify(serviceBody(form, false))
	});
	setNotice("Service saved.", "success");
	await services();
}
